177	// Drives the app through its screens, binding only to data-testid (AGENTS.md §2). Every test
178	// arranges its own data with these helpers and asserts through them or through data-testid
179	// directly. An action helper returns what the screen reported: an id when a row was created,
180	// true/false for whether the action went through or the screen refused it (its error element
181	// appeared). It throws when neither a result nor an error shows within the wait, so a screen that
182	// does nothing fails the test instead of passing as "refused".
183	import { expect, type Browser, type Locator, type Page } from '@playwright/test';
184	import { existsSync, readFileSync } from 'node:fs';
185	
186	const AUDIT_FILE = process.env.AUDIT_FILE ?? '../.run/audit.log';
187	const WAIT = 8000;
188	const ERROR_GRACE = 500;      // how long an error left over from the action before may linger
189	const AUDIT_WAIT = 3000;      // how long an audit line may lag the screen
190	
191	const editing = new WeakMap<Page, string>();
192	
193	export function sheetId(): string {
194	  return 's' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
195	}
196	
197	/** The id a creating helper returned; throws when the screen refused (null) so the failure
198	 *  lands on the arranging line rather than on a later assertion. */
199	export function must(id: string | null): string {
200	  if (id === null) throw new Error('the screen refused this action (its error element appeared)');
201	  return id;
202	}
203	
204	function escapeRe(s: string): string {
205	  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
206	}
207	
208	/** The trimmed text of a locator, read without waiting: '' when it is not on the page. A poll
209	 *  must never use an auto-waiting read (textContent, getAttribute) on an element that may be
210	 *  re-rendered or removed while it polls; that read would block until the test's own timeout. */
211	async function shown(loc: Locator): Promise<string> {
212	  return ((await loc.allTextContents())[0] ?? '').trim();
213	}
214	
215	/** The ids carried by every element matching `loc`, read without waiting. */
216	async function ids(loc: Locator, prefix: string): Promise<string[]> {
217	  const out: string[] = [];
218	  for (const h of await loc.elementHandles()) out.push(idOf(await h.getAttribute('data-testid'), prefix));
219	  return out;
220	}
221	
222	function idOf(testid: string | null, prefix: string): string {
223	  if (!testid || !testid.startsWith(prefix)) throw new Error(`no ${prefix}* id on ${testid}`);
224	  return testid.slice(prefix.length);
225	}
226	
227	/** Poll until `done` holds (true) or `error` is visible (false); throw when neither happens.
228	 *  Each check returns as soon as it can. An error already visible at the first look after the
229	 *  click may be left over from the action before (the screen clears it when a new action is
230	 *  submitted, see README): it counts as this action's refusal once it has gone away and been
231	 *  shown again, once its text changes, or once ERROR_GRACE has passed with no result. */
232	async function until(page: Page, done: () => Promise<boolean>, error: Locator, what: string): Promise<boolean> {
233	  const deadline = Date.now() + WAIT;
234	  let stale: string | null | undefined;   // text of an error visible at the first look; null if none
235	  let seenGone = false;
236	  const grace = Date.now() + ERROR_GRACE;
237	  while (Date.now() < deadline) {
238	    if (await done()) return true;
239	    const visible = await error.isVisible().catch(() => false);
240	    if (stale === undefined) stale = visible ? await shown(error) : null;
241	    if (visible) {
242	      if (stale === null || seenGone || (await shown(error)) !== stale || Date.now() >= grace) return false;
243	    } else {
244	      seenGone = true;
245	    }
246	    await page.waitForTimeout(50);
247	  }
248	  if (await done()) return true;
249	  if (await error.isVisible().catch(() => false)) return false;
250	  throw new Error(`${what}: neither a result nor an error appeared within ${WAIT}ms`);
251	}
252	
253	async function sleep(ms: number): Promise<void> {
254	  await new Promise((r) => setTimeout(r, ms));
255	}
256	
257	/** A counter the screen shows after a bulk action: the number in the cell once it is visible. */
258	async function counter(page: Page, cell: Locator, error: Locator, what: string): Promise<number | null> {
259	  const ok = await until(page, async () => (await cell.count()) > 0 && (await shown(cell)) !== '', error, what);
260	  return ok ? Number(await shown(cell)) : null;
261	}
