281	/** Re-load the active sheet so the screen shows what the store holds now. Loading the same id
282	 *  again is not observable (the current id already reads that), so the screen first loads a
283	 *  throwaway id, which must change the current id, then the sheet again; it is back once every
284	 *  person row from before is on screen with at least as many claims as before. The show-retired
285	 *  box and the as-of date, which belong to the screen, are put back if the loads reset them. */
286	export async function refresh(page: Page): Promise<void> {
287	  const sheet = (await page.getByTestId('sheet-current-id').textContent() ?? '').trim();
288	  const before = new Map<string, number>();
289	  for (const id of await ids(rows(page), 'person-row-')) before.set(id, await claimRows(row(page, id)).count());
290	  const retired = page.getByTestId('show-retired');
291	  const showRetiredWas = (await retired.count()) > 0 ? await retired.isChecked() : null;
292	  const asofWas = await shown(page.getByTestId('sheet-asof'));
293	  await loadSheet(page, sheet + '-reload');
294	  await loadSheet(page, sheet);
295	  if (showRetiredWas !== null && (await retired.isChecked()) !== showRetiredWas) await retired.setChecked(showRetiredWas);
296	  if (asofWas !== '' && (await shown(page.getByTestId('sheet-asof'))) !== asofWas) await setAsOf(page, asofWas);
297	  await expect.poll(async () => {
298	    for (const [id, n] of before) {
299	      const r = row(page, id);
300	      if ((await r.count()) === 0 || (await claimRows(r).count()) < n) return false;
301	    }
302	    return true;
303	  }, { message: 'the sheet is back on screen after a reload', timeout: WAIT }).toBe(true);
