842	/** The audit lines written for this sheet, in file order. */
843	export function auditFor(sheet: string): string[] {
844	  if (!existsSync(AUDIT_FILE)) return [];
845	  return readFileSync(AUDIT_FILE, 'utf8').split('\n').filter((l) => l.includes(` sheet=${sheet} `));
846	}
847	
848	/** The sheet's audit lines are exactly these, in order; a line may carry further fields after
849	 *  the expected ones (a later feature may extend a line, never change or reorder its fields).
850	 *  A line may land a moment after the screen shows its result, so the file is re-read until
851	 *  it has as many lines as expected (lines are only ever appended), for AUDIT_WAIT at most. */
852	export async function expectAudit(sheet: string, expected: string[]): Promise<void> {
853	  let lines = auditFor(sheet);
854	  const deadline = Date.now() + AUDIT_WAIT;
855	  while (lines.length < expected.length && Date.now() < deadline) {
856	    await sleep(50);
857	    lines = auditFor(sheet);
858	  }
859	  expect(lines.length, `audit lines for ${sheet}:\n${lines.join('\n')}`).toBe(expected.length);
860	  lines.forEach((line, i) => {
861	    const e = expected[i];
862	    const ok = line === e || line.startsWith(e + ' ');
863	    expect(ok, `audit line ${i + 1}\n  expected: ${e}\n  actual:   ${line}`).toBe(true);
864	  });
865	}
